insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_119'
from (values
('127.822.d.1.A',3,'Keisha plans to apply to a Texas welding technology program. She compares entrance requirements, tuition and the exams she must pass first. She is determining:','["academic knowledge and skills required for postsecondary education", "only the football team", "only the weather at the campus", "only the dorm colors"]'::jsonb,0,'Entry requirements guide planning.','original'),
('127.822.d.1.A',4,'Which activity best helps a junior prepare for a college-level welding program?','["skipping career fairs", "completing algebra and geometry while building weld test coupons", "dropping all math classes", "avoiding the shop"]'::jsonb,1,'Math and hands-on practice both count.','original'),
('127.822.d.1.B',3,'The owner of a machine repair shop says repeat customers come from quick turnaround and welds that do not crack. These employer expectations promote:','["higher turnover", "more complaints", "positive customer satisfaction", "fewer orders"]'::jsonb,2,'Satisfied customers return.','original'),
('127.822.d.1.B',4,'A customer asks a welder to match the color and finish of an old gate. The best way to meet the expectation is to:','["tell the customer to do it", "guess the color", "skip the finish", "confirm the details and show a sample before finishing"]'::jsonb,3,'Confirm requirements.','original'),
('127.822.d.1.C',3,'During a mock job interview, Andre shakes hands, answers with eye contact and brings copies of his certifications. This demonstrates professional standards such as:','["interviewing skills", "avoidance", "distraction", "tardiness"]'::jsonb,0,'Interviews are a professional standard.','original'),
('127.822.d.1.C',4,'Which item should a welder bring to an employment interview?','["a grinder", "a résumé and copies of certifications", "nothing at all", "a bag of scrap"]'::jsonb,1,'Documents show qualifications.','original'),
('127.822.d.1.D',3,'Every six weeks, Marcus compares his certifications and test results to the list he wrote for his career goal. He is evaluating:','["next year''s prices", "a coworker''s pay", "progress toward personal career goals", "his lunch plans"]'::jsonb,2,'Compare progress with goals.','original'),
('127.822.d.1.D',4,'Marcus notices he is behind on his hours toward an inspector credential. His best next step is to:','["drop the goal", "wait without a plan", "hide the record", "adjust his schedule to add hours"]'::jsonb,3,'Use the evaluation to adjust.','original'),
('127.822.d.1.E',3,'Before the night crew starts a pipe job, the lead walks through the drawing, the joint prep and the inspection point with each welder. This is communicating to:','["clarify objectives in the workplace", "slow the schedule", "complicate the job", "avoid training"]'::jsonb,0,'Briefings align the team.','original'),
('127.822.d.1.E',4,'A welder is unsure which pass sequence the supervisor wants. The best communication choice is to:','["skip the job", "ask for the written procedure and confirm it", "pick a sequence at random", "wait silently"]'::jsonb,1,'Clarify the procedure.','original'),
('127.822.d.1.F',3,'A shop keeps a first-aid kit, posts emergency exits and trains workers in lockout/tagout. These practices apply:','["sales quotas", "marketing rules", "health and safety knowledge as specified by OSHA", "parking rules"]'::jsonb,2,'OSHA safety knowledge.','original'),
('127.822.d.1.F',4,'If a welder gets a flash burn in the eyes, the best action is to:','["ignore it until tomorrow", "rub the eyes", "keep working", "seek first aid and report the incident"]'::jsonb,3,'Report and treat injuries.','original'),
('127.822.d.2.A',3,'A shop owner needs the cost of 12 brackets that use 3 ft of angle at $4 per ft each, plus $18 in wire for the whole job. The estimate is:','["$162", "$144", "$48", "$216"]'::jsonb,0,'12×3×4 = 144; +18 = 162.','original'),
('127.822.d.2.A',4,'A job needs 40 hours of labor at $32 an hour, $560 of material and 15% overhead on the total. The estimate is:','["$2,208", "$2,116", "$1,900", "$1,840"]'::jsonb,1,'1,280+560=1,840; ×1.15 = 2,116.','original'),
('127.822.d.2.B',3,'If a welder misreads a tape and cuts every beam 1/4 in. too long, the cost estimate will be:','["exact", "unaffected", "too low because of waste and rework not planned", "too high because of savings"]'::jsonb,2,'Errors add waste and rework.','original'),
('127.822.d.2.B',4,'Accurate readings of measuring devices reduce costs mainly by:','["increasing scrap", "adding delay", "hiding errors", "reducing scrap and rework"]'::jsonb,3,'Accuracy saves money.','original'),
('127.822.d.2.C',3,'To check the thickness of a plate to the nearest thousandth of an inch, a welder should choose a:','["micrometer", "tape measure", "carpenter''s rule", "yardstick"]'::jsonb,0,'Micrometers read thousandths.','original'),
('127.822.d.2.C',4,'Justify the choice of a long tape measure rather than a caliper to check a 20-ft beam: the tape is better because it:','["never needs reading", "can measure long lengths reasonably accurately", "measures thousandths", "fits in a pocket only"]'::jsonb,1,'Match tool to task.','original'),
('127.822.d.2.D',3,'A cylinder 10 in. across (radius 5 in.) is 8 in. tall. Using π ≈ 3.14, its volume is closest to:','["251 cubic inches", "314 cubic inches", "628 cubic inches", "400 cubic inches"]'::jsonb,2,'3.14×25×8 = 628.','original'),
('127.822.d.2.D',4,'The perimeter of a rectangular frame 30 in. by 18 in. is:','["66 in.", "540 in.", "48 in.", "96 in."]'::jsonb,3,'2×(30+18) = 96.','original'),
('127.822.d.2.E',3,'A welder adds 6 3/8 in., 4.5 in. and 2 1/8 in. The total is:','["13 in.", "13 3/8 in.", "14 in.", "12 in."]'::jsonb,0,'6.375+4.5+2.125 = 13.','original'),
('127.822.d.2.E',4,'A welder must cut 7/8 in. from each of 6 identical pieces. The total length removed is:','["5 1/2 in.", "5 1/4 in.", "4 3/4 in.", "5 in."]'::jsonb,1,'6×0.875 = 5.25.','original'),
('127.822.d.2.F',3,'A ramp frame has a base of 12 ft and a rise of 5 ft. The sloped length is:','["7 ft", "17 ft", "13 ft", "15 ft"]'::jsonb,2,'144+25=169; √169=13.','original'),
('127.822.d.2.F',4,'A diagonal brace runs 9 ft on one leg and 12 ft on the other. Its length is:','["13 ft", "21 ft", "18 ft", "15 ft"]'::jsonb,3,'81+144=225; √225=15.','original'),
('127.822.d.2.G',3,'To estimate the amount of steel needed for a rectangular plate, the best formula is:','["length times width times thickness", "width divided by length", "length plus width", "length minus thickness"]'::jsonb,0,'Volume of a rectangular solid.','original'),
('127.822.d.2.G',4,'To estimate weld metal for a groove joint, the cross-sectional area of the groove is multiplied by the:','["color of the plate", "length of the joint", "brand of the wire", "shift time"]'::jsonb,1,'Volume = area × length.','original'),
('127.822.d.3.A',3,'Before running a job, Tasha checks that guards are in place and the machine''s cable and ground are in good condition. She is:','["selling equipment", "moving the shop", "using welding equipment according to safety standards", "ignoring standards"]'::jsonb,2,'Pre-use checks.','original'),
('127.822.d.3.A',4,'A welder finds a cracked cable lug on the machine. The correct step is to:','["tape it", "use it anyway", "hide it", "tag it out of service until repaired"]'::jsonb,3,'Defective equipment is removed.','original'),
('127.822.d.3.B',3,'A spent can of cleaning solvent and contaminated rags from the shop should be:','["placed in approved waste containers for hazardous disposal", "put in the regular trash", "poured into the drain", "dumped outside"]'::jsonb,0,'Dispose hazardous waste properly.','original'),
('127.822.d.3.B',4,'Disposing of used solvent in a storm drain is wrong because it can:','["improve soil", "contaminate soil and water supplies", "help plants grow", "purify water"]'::jsonb,1,'Hazardous materials pollute.','original'),
('127.822.d.3.C',3,'A fabrication shop recycles scrap steel, copper and aluminum off-cuts instead of landfilling them. A student explains this saves:','["only paint", "only time", "raw materials, energy and landfill space", "nothing"]'::jsonb,2,'Recycling conserves resources.','original'),
('127.822.d.3.C',4,'Which statement correctly describes recycling in a welding shop?','["burying scrap is best", "mixing all metals is best", "avoid separating", "separating metals by type makes recycling more efficient"]'::jsonb,3,'Sorted scrap is worth more.','original'),
('127.822.d.3.D',3,'A company tests a new welding power source with pulsed waveforms and compares weld quality and speed with its old machine. This is evaluating:','["the performance impact of an emerging technology", "a uniform", "an old tradition", "a payroll plan"]'::jsonb,0,'New tech is judged on performance.','original'),
('127.822.d.3.D',4,'A real benefit that can result from new welding technology is:','["slower output", "faster production with consistent weld quality", "more scrap", "poorer control"]'::jsonb,1,'Emerging technologies improve efficiency.','original'),
('127.822.d.3.E',3,'Following the shop''s safety measures, a welder puts on a flame-resistant jacket, safety glasses under the helmet and hearing protection near the grinders. She is:','["ignoring safety", "ordering parts", "using appropriate personal protective equipment", "arranging a meeting"]'::jsonb,2,'PPE follows safety measures.','original'),
('127.822.d.3.E',4,'Welding in a closed space with poor airflow, the worker should add:','["a heavier jacket only", "more heat", "more rods", "a respirator or forced ventilation"]'::jsonb,3,'Fume protection.','original'),
('127.822.d.3.F',3,'A shop investigates robots that weld the same bracket thousands of times, programmed by numerical control and computer files. This is learning about:','["automated welding machines", "hand drawing", "manual painting", "office filing"]'::jsonb,0,'Automation uses numerical control.','original'),
('127.822.d.3.F',4,'A common reason a shop adds an automated welding cell is to:','["stop using electricity", "achieve consistent welds on repeated parts", "avoid all inspection", "eliminate quality checks"]'::jsonb,1,'Automation gives repeatability.','original'),
('127.822.d.4.A',3,'A student reads the print, the bill of materials and the tolerances to build a trailer hitch project from start to finish. She is using:','["guessing", "memory only", "knowledge of engineering drawings to complete an advanced project", "a coin toss"]'::jsonb,2,'Drawings guide the build.','original'),
('127.822.d.4.A',4,'A bill of materials on a drawing lists:','["the shop''s address only", "the welder''s pay", "the customer''s lunch", "the parts and quantities needed"]'::jsonb,3,'BOMs list parts.','original'),
('127.822.d.4.B',3,'After finishing a bracket, Noor checks each dimension and weld size against the drawing. She is:','["evaluating the project using drawing specifications", "pricing the part", "painting the part", "packing the part"]'::jsonb,0,'Compare finished work to the print.','original'),
('127.822.d.4.B',4,'If a measured hole is outside the tolerance on the print, the part should be:','["hidden", "reworked or rejected according to the specification", "shipped as is", "painted over"]'::jsonb,1,'Out-of-tolerance parts fail.','original'),
('127.822.d.5.A',3,'Given a print and material, Luis fabricates a small steel table with little help from the instructor. He is:','["avoiding the print", "waiting for help", "working independently to fabricate a welded project", "only copying a coworker"]'::jsonb,2,'Independent fabrication.','original'),
('127.822.d.5.A',4,'When fabricating independently, a welder should still:','["ignore the print", "guess dimensions", "skip layout", "verify the fit-up and dimensions before welding"]'::jsonb,3,'Check before welding.','original'),
('127.822.d.5.B',3,'Two students split a job to build a trailer, one cutting and fitting, the other welding and inspecting, and then swap roles. They are:','["working collaboratively on a real-world project", "avoiding the job", "working alone", "working against each other"]'::jsonb,0,'Collaboration on real projects.','original'),
('127.822.d.5.B',4,'A good practice when two welders share one project is to:','["ignore the other welder", "agree on the sequence and communicate before moving parts", "work without talking", "move parts without notice"]'::jsonb,1,'Communication prevents accidents.','original'),
('127.822.d.5.C',3,'A wire welder starts to feed erratically and the arc sputters. Valeria checks the drive rolls, liner and tension. She is:','["ignoring the problem", "selling equipment", "troubleshooting equipment", "drawing a part"]'::jsonb,2,'Systematic troubleshooting.','original'),
('127.822.d.5.C',4,'A stick welder will not strike an arc. The first thing to check is:','["the customer''s invoice", "the shop''s lights", "the paint color", "the ground clamp connection and cable"]'::jsonb,3,'Poor ground is a common cause.','original'),
('127.822.d.7.A',3,'Before cutting with oxy-fuel, Imani clears flammables, wears eye protection and keeps an extinguisher close. She is:','["observing safe operating practices", "skipping steps", "ignoring risks", "speeding up"]'::jsonb,0,'Cutting safety.','original'),
('127.822.d.7.A',4,'Sparks from cutting can travel many feet, so the operator should:','["remove the extinguisher", "remove or cover combustibles within the work zone", "ignore the sparks", "leave rags nearby"]'::jsonb,1,'Hot work precautions.','original'),
('127.822.d.7.B',3,'After the shift, a cylinder cart is secured upright, valves closed and caps on. This shows:','["random handling", "unsafe handling", "safe handling of compressed gases", "wasteful handling"]'::jsonb,2,'Cylinder safety.','original'),
('127.822.d.7.B',4,'Oxygen cylinders and fuel gas cylinders in storage should be:','["stored together without separation", "stored near heat", "left lying down", "separated and secured upright"]'::jsonb,3,'Separate and secure.','original'),
('127.822.d.7.C',3,'A student follows an accepted standard to pierce, cut a straight line and bevel an edge in plate. She is performing cutting processes:','["according to accepted welding standards", "without safety", "in random order", "by guess"]'::jsonb,0,'Standards define good cuts.','original'),
('127.822.d.7.C',4,'A bevel cut prepares plate for:','["storage", "a groove weld", "painting", "drilling only"]'::jsonb,1,'Bevels enable groove welds.','original'),
('127.822.d.8.A',3,'Before an overhead weld, Gabe checks his gloves, jacket and cap and puts a cap over his helmet to keep sparks out of his hair. He is:','["skipping steps", "ignoring risks", "employing safe operating practices", "speeding up"]'::jsonb,2,'Overhead welding safety.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_119'
from (values
('127.822.d.8.A',4,'Overhead welding creates a hazard of:','["cooler air", "less light", "extra gas", "falling sparks and molten metal"]'::jsonb,3,'Dress to shed sparks.','original'),
('127.822.d.8.B',3,'To pass a qualification test, Hana welds coupons in flat, horizontal, vertical and overhead positions and meets the standard''s criteria. She is:','["making welds in all positions according to industry standards", "only tacking", "avoiding standards", "doing it once"]'::jsonb,0,'Qualification tests require all positions.','original'),
('127.822.d.8.B',4,'A welder qualification test is judged by:','["a coin toss", "visual inspection and bend or other tests per the code", "the welder''s guess", "the appearance of the helmet"]'::jsonb,1,'Tests follow the code.','original'),
('127.822.d.9.A',3,'Before a wire-feed job, Omar secures the cylinder, checks the gas flow and clears the area of flammables. He is:','["skipping steps", "ignoring safety", "using safe operating practices", "guessing"]'::jsonb,2,'GMAW safety.','original'),
('127.822.d.9.A',4,'Leaking shielding gas in a small closed room is dangerous because it can:','["cool the metal", "add oxygen", "improve weld quality", "displace oxygen"]'::jsonb,3,'Inert gases displace oxygen.','original'),
('127.822.d.9.B',3,'A student welds a T-joint and a beveled V-groove joint with wire feed. She is performing:','["fillet and groove welds", "only cutting", "only painting", "only grinding"]'::jsonb,0,'Basic joint types.','original'),
('127.822.d.9.B',4,'Which joint requires beveling the plate edges before welding?','["a spot weld on sheet", "a V-groove butt joint on thick plate", "a thin lap joint", "a surface weld"]'::jsonb,1,'Thick butt joints need prep.','original'),
('127.822.d.9.C',3,'On a certification test, a welder must weld in each assigned position and pass the bend test. This demonstrates welding in:','["any position without limits", "one position only", "all appropriate positions according to industry-accepted standards", "no position"]'::jsonb,2,'Certification covers positions.','original'),
('127.822.d.9.C',4,'Which statement about welding positions on a certification test is correct?','["welders may choose any", "positions do not matter", "the helmet decides", "the position is stated by the test code and must be followed"]'::jsonb,3,'The code determines the positions.','original'),
('127.822.d.10.A',3,'Before running a TIG job on stainless, Rae clears the solvents, checks the gas and wears the correct lens. She is:','["employing safe operating practices", "skipping steps", "ignoring safety", "speeding up"]'::jsonb,0,'GTAW safety.','original'),
('127.822.d.10.A',4,'The arc light from TIG welding is intense, so the welder should:','["look away only", "wear a helmet with the proper shade lens", "use sunglasses", "wear nothing"]'::jsonb,1,'Eye protection.','original'),
('127.822.d.10.B',3,'A welder runs fillet and groove welds in the flat, vertical and overhead positions using TIG. She is:','["only flat welding", "only cutting", "performing fillet and groove welds in all positions", "only brazing"]'::jsonb,2,'All-position practice.','original'),
('127.822.d.10.B',4,'TIG welding is often chosen for thin metals because it:','["burns through quickly", "cannot control heat", "needs no skill", "allows precise heat control"]'::jsonb,3,'Precise control.','original'),
('127.822.d.10.C',3,'A shop welds a stainless tank, an aluminum frame and a carbon steel pipe in the same week, selecting the filler and settings for each. This is performing welds on:','["a variety of metals", "only one metal", "wood", "glass"]'::jsonb,0,'Different metals need different settings.','original'),
('127.822.d.10.C',4,'Aluminum is commonly TIG welded with:','["oxygen only", "alternating current and argon shielding", "acetylene", "direct current only with no gas"]'::jsonb,1,'AC cleans the oxide.','original'),
('127.823.d.1.A',3,'A welder writes a short email to a supervisor explaining that a plate arrived 1/8 in. undersized and asks how to proceed. The email works well because it is:','["full of slang", "long and vague", "clear, concise and effective", "angry and rushed"]'::jsonb,2,'Good writing is clear and brief.','original'),
('127.823.d.1.A',4,'Which sentence best expresses an idea in a clear, concise manner?','["Stuff went wrong with the plate and things.", "Something happened, you know.", "It''s all messed up, whatever.", "The 3/8 in. plate failed the bend test; please advise on a retest."]'::jsonb,3,'Specific and brief.','original'),
('127.823.d.1.B',3,'A lead writes work instructions with numbered steps, units and a sketch so that any new hire can follow them. This is conveying written information that is:','["easily understandable to others", "confusing", "hidden", "incomplete"]'::jsonb,0,'Steps and sketches clarify.','original'),
('127.823.d.1.B',4,'A welder''s written note about a repair should include:','["only the weather", "what was done, where and when", "no details", "only a complaint"]'::jsonb,1,'Useful records are specific.','original'),
('127.823.d.1.C',3,'Sam reports to work on time, stays through the end of the shift, and finishes every task assigned. He is demonstrating:','["poor habits", "laziness", "acceptable work ethics", "avoidance"]'::jsonb,2,'Reliability is a work ethic.','original'),
('127.823.d.1.C',4,'A welder who will be late because of a car problem should:','["blame a coworker", "skip work without notice", "say nothing", "call the supervisor as early as possible"]'::jsonb,3,'Communicate absences.','original'),
('127.823.d.1.D',3,'On a job site, Dee wears clean PPE, uses respectful language with the inspector and keeps her cell phone put away while working. She is conducting herself:','["in a manner acceptable for the profession and work site", "casually", "unsafely", "rudely"]'::jsonb,0,'Professional conduct.','original'),
('127.823.d.1.D',4,'Which behavior is appropriate on a welding job site?','["arguing with customers", "following dress code and speaking respectfully", "using phones during welding", "ignoring the dress code"]'::jsonb,1,'Professionalism at work.','original'),
('127.823.d.1.E',3,'A welder finds that a coworker has signed off a weld without inspection. Choosing the ethical action, she should:','["sign it too", "ignore the rules", "report it to the supervisor following company policy", "hide it"]'::jsonb,2,'Integrity and compliance.','original'),
('127.823.d.1.E',4,'Falsifying a weld inspection record is:','["required by codes", "acceptable", "a shortcut", "unethical and may be illegal"]'::jsonb,3,'Honesty is required.','original'),
('127.823.d.1.F',3,'A quality technician reviews every field on a weld procedure, from the preheat temperature to the interpass limits, to be sure each detail is correct. This is:','["reviewing the fine, detailed aspects of work processes", "skimming quickly", "guessing", "ignoring the details"]'::jsonb,0,'Attention to detail.','original'),
('127.823.d.1.F',4,'A small error in a welding procedure, such as the wrong electrode, can:','["have no effect", "cause a failed weld and costly rework", "improve quality", "save money"]'::jsonb,1,'Details matter.','original'),
('127.823.d.1.G',3,'After several pipe welds fail inspection, a lead compares the failed welds, notices they were all made after the machine was moved and traces the problem to a poor ground. She is:','["blaming people", "guessing", "evaluating operations and identifying causes and patterns", "ignoring data"]'::jsonb,2,'Systematic analysis.','original'),
('127.823.d.1.G',4,'Which approach best identifies the cause of repeated weld defects?','["blame the newest welder", "ignore the failures", "skip the inspection", "look for patterns across the failed welds"]'::jsonb,3,'Patterns reveal causes.','original'),
('127.823.d.1.H',3,'A welder follows the shop''s written procedure, then adds the supervisor''s verbal change to the form. She is:','["following written and oral instructions and business practices", "skipping documentation", "ignoring instructions", "working alone"]'::jsonb,0,'Adhere to practice.','original'),
('127.823.d.1.H',4,'If an oral instruction conflicts with the written procedure, the welder should:','["guess", "ask the supervisor to clarify and document the change", "ignore both", "follow whichever is easier"]'::jsonb,1,'Clarify conflicts.','original'),
('127.823.d.1.I',3,'A welder lists tomorrow''s jobs, puts the rush order first and plans cutting before welding so the shop stays on schedule. She is:','["working randomly", "procrastinating", "prioritizing tasks and following schedules", "ignoring tasks"]'::jsonb,2,'Prioritization.','original'),
('127.823.d.1.I',4,'When two jobs are due at the same time, a welder should:','["choose without asking", "skip both", "start both and finish neither", "ask which one is more urgent and plan accordingly"]'::jsonb,3,'Prioritize with input.','original'),
('127.823.d.2.A',3,'Before pressing the trigger, Joel inspects the machine, checks the ground and clears flammables. He is:','["using welding equipment according to safety standards", "moving equipment", "ignoring standards", "selling equipment"]'::jsonb,0,'Equipment safety.','original'),
('127.823.d.2.A',4,'If a welder smells burning insulation near the machine, the best response is to:','["ignore it", "shut it down and report it", "splash water on it", "keep welding"]'::jsonb,1,'Electrical hazard.','original'),
('127.823.d.2.B',3,'Oily rags, spent solvents and used flux are collected in labeled bins for pickup. This shows how to:','["burn waste", "dump waste", "identify and properly dispose of hazardous materials", "ignore waste"]'::jsonb,2,'Proper disposal.','original'),
('127.823.d.2.B',4,'The safety data sheet for a cleaning solvent tells a welder:','["its color only", "nothing useful", "its price", "its hazards, handling and disposal needs"]'::jsonb,3,'SDS gives hazards.','original'),
('127.823.d.2.C',3,'A shop''s recycling program for scrap metal supports:','["conservation of resources and less landfill", "more landfill", "waste of energy", "higher pollution"]'::jsonb,0,'Recycling conserves.','original'),
('127.823.d.2.C',4,'Which welding by-product is commonly recycled?','["welding smoke", "scrap metal off-cuts", "arc light", "slag dust only"]'::jsonb,1,'Metal scrap is recycled.','original'),
('127.823.d.2.D',3,'A welder chooses a respirator for fumes, gloves rated for heat and a helmet with the correct lens. These are:','["office supplies", "fashion items", "appropriate personal protective equipment", "unneeded extras"]'::jsonb,2,'PPE selection.','original'),
('127.823.d.2.D',4,'When grinding after welding, the welder should add:','["no protection", "sandals", "a hat only", "a face shield over safety glasses"]'::jsonb,3,'Grinding adds flying debris.','original'),
('127.823.d.3.A',3,'Given a drawing and the stock, Ravi cuts, fits and welds a utility trailer with only an occasional question to the instructor. He is:','["working independently to fabricate welded projects with minimal assistance", "avoiding responsibility", "waiting for help", "only following a lead"]'::jsonb,0,'Independence.','original'),
('127.823.d.3.A',4,'A welder working independently should still:','["skip inspection", "inspect the work against the drawing before finishing", "guess sizes", "ignore the drawing"]'::jsonb,1,'Self-check.','original'),
('127.823.d.3.B',3,'On a class project, three students divide tasks, share tools and review each other''s welds before assembly. They are:','["avoiding tasks", "competing", "working collaboratively to complete a project", "working alone"]'::jsonb,2,'Collaboration.','original'),
('127.823.d.3.B',4,'The best way for a team to finish a project on time is to:','["work at random", "avoid talking", "ignore deadlines", "assign roles and communicate progress"]'::jsonb,3,'Roles and communication.','original'),
('127.823.d.3.C',3,'When a wire welder will not feed, Elena checks the drive rolls, the liner and the spool brake in order. She is:','["troubleshooting equipment", "ignoring equipment", "painting equipment", "selling equipment"]'::jsonb,0,'Troubleshooting is methodical.','original'),
('127.823.d.3.C',4,'A weld with heavy porosity may be traced to:','["the shop''s lights", "a shielding gas problem or contaminated metal", "the welder''s shoes", "too much paint on the helmet"]'::jsonb,1,'Common causes.','original'),
('127.823.d.4.A',3,'An inspector uses a flashlight, a mirror, a gauge and a camera to examine a weld, then records what she finds. She is explaining:','["packing methods", "painting methods", "weld inspection processes", "cooking methods"]'::jsonb,2,'Inspection process.','original'),
('127.823.d.4.A',4,'A destructive test used to check weld quality is:','["a paint test", "a visual look only", "a photo", "a guided bend test"]'::jsonb,3,'Bend tests break samples.','original'),
('127.823.d.4.B',3,'A student welds a test coupon to meet the acceptance criteria in a structural welding code. She is producing:','["acceptable weldments to industry code standards", "unfinished welds", "random welds", "guessed welds"]'::jsonb,0,'Code compliance.','original'),
('127.823.d.4.B',4,'A weld that meets code has defects within:','["no limits", "the code''s acceptance limits", "the welder''s opinion", "any size"]'::jsonb,1,'Codes set limits.','original'),
('127.823.d.5.A',3,'Before lighting a torch, Brin checks for flammables, wears the correct PPE and has a spark lighter ready. She is:','["skipping steps", "ignoring risks", "using safe operating practices", "guessing"]'::jsonb,2,'Torch safety.','original'),
('127.823.d.5.A',4,'A torch that backfires with a pop should be:','["left on", "relit immediately", "ignored", "shut off and inspected before relighting"]'::jsonb,3,'Backfires indicate a problem.','original'),
('127.823.d.5.B',3,'At the end of the day, the oxygen and fuel gas cylinders are valved off, capped and chained upright. This is:','["safe handling of compressed gases", "random handling", "unsafe handling", "careless handling"]'::jsonb,0,'Cylinder handling.','original'),
('127.823.d.5.B',4,'Moving a cylinder with its cap off by rolling it on the valve is:','["recommended", "unsafe because the valve can break", "acceptable", "safe"]'::jsonb,1,'Cap on, secure.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
